CREATE TABLE IF NOT EXISTS official_ai_config(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL,model TEXT NOT NULL,daily_limit INTEGER NOT NULL,monthly_tokens INTEGER NOT NULL,key_cipher TEXT,key_hint TEXT,updated INTEGER NOT NULL,updated_by TEXT);
CREATE TABLE IF NOT EXISTS ai_upstreams(id TEXT PRIMARY KEY,seq INTEGER UNIQUE NOT NULL,position INTEGER NOT NULL,note TEXT NOT NULL,base_url TEXT NOT NULL,model TEXT NOT NULL,key_cipher TEXT NOT NULL,key_hint TEXT NOT NULL,input_price INTEGER NOT NULL,output_price INTEGER NOT NULL,remaining INTEGER,expires INTEGER,enabled INTEGER NOT NULL,status TEXT NOT NULL,reason TEXT,status_at INTEGER,cooldown_until INTEGER NOT NULL DEFAULT 0,spent INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,calls INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_redeem_codes(id TEXT PRIMARY KEY,digest TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,points INTEGER NOT NULL,note TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created INTEGER NOT NULL,expires INTEGER NOT NULL,revoked INTEGER,redeemed INTEGER,user_id TEXT REFERENCES users(id),code_cipher TEXT,seq INTEGER);
CREATE TABLE IF NOT EXISTS official_ai_usage(user_id TEXT NOT NULL REFERENCES users(id),day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0,points INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,day));
